 "content": "from collections import deque


def _components(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            cells = set()
            queue = deque([(r, c)])
            seen.add((r, c))
            while queue:
                y, x = queue.popleft()
                cells.add((y, x))
                for ny, nx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if (0 <= ny < h and 0 <= nx < w and
                            (ny, nx) not in seen and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        queue.append((ny, nx))
            objects.append((color, cells))
    return objects


def _is_frame(cells):
    r0 = min(r for r, _ in cells)
    r1 = max(r for r, _ in cells)
    c0 = min(c for _, c in cells)
    c1 = max(c for _, c in cells)
    if r1 - r0 < 2 or c1 - c0 < 2:
        return False
    perimeter = {
        (r, c)
        for r in range(r0, r1 + 1)
        for c in range(c0, c1 + 1)
        if r in (r0, r1) or c in (c0, c1)
    }
    return cells == perimeter


def transform(grid):
    h, w = len(grid), len(grid[0])
    objects = _components(grid)
    frames = [(color, cells) for color, cells in objects if _is_frame(cells)]
    others = [(color, cells) for color, cells in objects if not _is_frame(cells)]
    result = [[0] * w for _ in range(h)]

    # Closed rectangular outlines rise to the top; objects with other shapes
    # fall to the bottom. Objects in each group settle without overlapping one
    # another, while the two groups move independently.
    for group, upward in ((frames, True), (others, False)):
        if upward:
            group = sorted(group, key=lambda item: min(r for r, _ in item[1]))
        else:
            group = sorted(group, key=lambda item: max(r for r, _ in item[1]), reverse=True)
        occupied = set()
        for color, cells in group:
            shift = 0
            while True:
                next_shift = shift + (1 if upward else -1)
                moved = {(r - next_shift, c) if upward else (r - next_shift, c) for r, c in cells}
                # In the downward case next_shift is negative, so subtraction moves down.
                if any(r < 0 or r >= h or (r, c) in occupied for r, c in moved):
                    break
                shift = next_shift
            for r, c in cells:
                nr = r - shift
                result[nr][c] = color
                occupied.add((nr, c))
    return result


